import React, { useRef, useEffect, useState } from "react";
import { Link } from "react-router-dom";
import styled, { keyframes, createGlobalStyle } from "styled-components";

/* -------- LAB PROGRAMS (existing folder) -------- */
import program1 from "../programs/program1";
import program2 from "../programs/program2";
import program3 from "../programs/program3";

/* -------- GENERAL PROGRAMS (new folder) -------- */
import program4 from "../programs/general/program1";


/* -------- Program Groups -------- */
const labPrograms = [program1, program2, program3];
const generalPrograms = [program4, program5, program6];

/* ---------------- Global ---------------- */
const Global = createGlobalStyle`
  :root{
    --bg: #080c11;
    --panel: rgba(255,255,255,0.035);
    --panelHover: rgba(255,255,255,0.06);
    --text: #eaf2fb;
    --muted: #9aa7b5;
    --accent: #70e6ff;
    --ring: rgba(112,230,255,0.33);
    --stroke: rgba(255,255,255,0.10);
    --focus: 0 0 0 4px var(--ring);
  }

  * { box-sizing: border-box; }
  html, body, #root { height: 100%; }

  body {
    margin: 0;
    color: var(--text);
    background:
      radial-gradient(1200px 700px at 15% -10%, #0e1520 0%, var(--bg) 55%),
      radial-gradient(1000px 600px at 100% 120%, #0b1118 0%, var(--bg) 60%);
    font-family: ui-sans-serif, system-ui, -apple-system, "SF Pro Display",
      Segoe UI, Inter, Roboto, Helvetica, Arial, sans-serif;
  }
`;

/* ---------------- Animations ---------------- */
const rise = keyframes`
  from { opacity: 0; transform: translateY(10px) scale(.985); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
`;

/* ---------------- Layout ---------------- */
const Container = styled.div`
  max-width: 1120px;
  margin: 0 auto;
  padding: 64px 18px 56px;
`;

const Hero = styled.header`
  text-align: center;
  margin-bottom: 32px;
  animation: ${rise} .6s ease both;

  h1{
    margin: 0;
    font-size: clamp(2rem, 5.5vw, 3.3rem);
    font-weight: 820;
    background: linear-gradient(90deg, #d9edff, var(--accent));
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
  }
`;

/* ---------------- Toggle ---------------- */
const ToggleWrap = styled.div`
  display: inline-flex;
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 999px;
  padding: 4px;
  margin: 0 auto 36px;
`;

const ToggleBtn = styled.button`
  border: none;
  background: ${({ active }) =>
    active ? "rgba(112,230,255,0.18)" : "transparent"};
  color: ${({ active }) => (active ? "var(--text)" : "var(--muted)")};
  padding: 8px 22px;
  border-radius: 999px;
  font-weight: 600;
  cursor: pointer;
  transition: .2s;

  &:hover { color: var(--text); }
`;

/* ---------------- Grid & Cards ---------------- */
const Grid = styled.div`
  display: grid;
  gap: 18px;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
`;

const CardBase = styled(Link)`
  background: var(--panel);
  border: 1px solid var(--stroke);
  border-radius: 16px;
  padding: 18px;
  text-decoration: none;
  color: var(--text);
  transition: .2s;
  animation: ${rise} .4s ease both;

  &:hover {
    transform: translateY(-4px);
    background: var(--panelHover);
  }
`;

const Title = styled.div`
  font-weight: 700;
`;

const Meta = styled.div`
  margin-top: 8px;
  display: flex;
  gap: 8px;
  font-size: .85rem;
  color: var(--muted);

  span{
    border: 1px solid var(--stroke);
    padding: 2px 8px;
    border-radius: 999px;
  }
`;

/* ---------------- Footer ---------------- */
const Footer = styled.footer`
  margin-top: 44px;
  text-align: center;
  font-size: .9rem;
  color: var(--muted);

  a{
    color: var(--accent);
    text-decoration: none;
    font-weight: 600;
  }
`;

/* ---------------- Page ---------------- */
export default function Dashboard() {
  const [mode, setMode] = useState("lab");

  const programs =
    mode === "lab" ? labPrograms : generalPrograms;

  return (
    <>
      <Global />
      <Container>
        <Hero>
          <h1>Java Programs</h1>
        </Hero>

        {/* TOGGLE */}
        <div style={{ display: "flex", justifyContent: "center" }}>
          <ToggleWrap>
            <ToggleBtn
              active={mode === "lab"}
              onClick={() => setMode("lab")}
            >
              Lab Programs
            </ToggleBtn>
            <ToggleBtn
              active={mode === "general"}
              onClick={() => setMode("general")}
            >
              General Programs
            </ToggleBtn>
          </ToggleWrap>
        </div>

        {/* PROGRAM LIST */}
        <Grid key={mode}>
          {programs.map((p, idx) => (
            <CardBase
              key={p.id}
              to={`/program/${p.id}`}
              style={{ animationDelay: `${idx * 0.04}s` }}
            >
              <Title>{p.title}</Title>
              <Meta>
                <span>#{p.id}</span>
                <span>Java</span>
              </Meta>
            </CardBase>
          ))}
        </Grid>

        <Footer>
          <a
            href="https://www.instagram.com/_zainn.27"
            target="_blank"
            rel="noreferrer"
          >
            @_zainn.27
          </a>
        </Footer>
      </Container>
    </>
  );
}
